using MongoDB.Driver;
namespace AILearnAPI.Api.Features.NotesRecall;
public sealed class NotesRecallRepository{readonly IMongoCollection<NoteRecallContent> c;readonly IMongoCollection<NoteRecallSession>s;readonly IMongoCollection<NoteRecallAttempt>a;readonly IMongoCollection<NoteRecallItem>i;public NotesRecallRepository(IMongoDatabase db){c=db.GetCollection<NoteRecallContent>("NoteRecallContents");s=db.GetCollection<NoteRecallSession>("NoteRecallSessions");a=db.GetCollection<NoteRecallAttempt>("NoteRecallAttempts");i=db.GetCollection<NoteRecallItem>("NoteRecallItems");}public Task<NoteRecallContent?>Content(string n,string u)=>c.Find(x=>x.NoteId==n&&x.UserId==u).FirstOrDefaultAsync()!;public async Task SaveContent(NoteRecallContent x)=>await c.ReplaceOneAsync(v=>v.NoteId==x.NoteId&&v.UserId==x.UserId,x,new ReplaceOptions{IsUpsert=true});public async Task<NoteRecallSession>Create(NoteRecallSession x){await s.InsertOneAsync(x);return x;}public Task<NoteRecallSession?>Session(string id,string u)=>s.Find(x=>x.Id==id&&x.UserId==u).FirstOrDefaultAsync()!;public Task Update(NoteRecallSession x)=>s.ReplaceOneAsync(v=>v.Id==x.Id&&v.UserId==x.UserId,x);public Task<NoteRecallAttempt?>Attempt(string key,string u)=>a.Find(x=>x.IdempotencyKey==key&&x.UserId==u).FirstOrDefaultAsync()!;public async Task<NoteRecallAttempt>Add(NoteRecallAttempt x){await a.InsertOneAsync(x);return x;}public Task<List<NoteRecallItem>>Due(string u)=>i.Find(x=>x.UserId==u&&!x.Mastered&&x.NextRevisionAt<=DateTime.UtcNow).SortBy(x=>x.NextRevisionAt).ToListAsync();public Task<List<NoteRecallItem>>All(string u)=>i.Find(x=>x.UserId==u).ToListAsync();public Task Upsert(NoteRecallItem x)=>i.ReplaceOneAsync(v=>v.UserId==x.UserId&&v.QuestionId==x.QuestionId,x,new ReplaceOptions{IsUpsert=true});public Task<NoteRecallItem?>Item(string id,string u)=>i.Find(x=>x.Id==id&&x.UserId==u).FirstOrDefaultAsync()!;public Task UpdateItem(NoteRecallItem x)=>i.ReplaceOneAsync(v=>v.Id==x.Id&&v.UserId==x.UserId,x);}
